const FLAGS = "";
const ALPHABET = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ-_";

export const lexiconIds: readonly string[] = IDS.split(" ").map((s) => s.replace(/_/g, " "));
export const lexiconSize = lexiconIds.length;
const ospmList = OSPM.split(",");
const index = new Map<string, number>();
lexiconIds.forEach((id, i) => index.set(id, i));
const bitsOf = (i: number): number => Math.max(0, ALPHABET.indexOf(FLAGS[i] ?? "0"));

function flagsOf(i: number): LexFlags {
  const bits = bitsOf(i);
  const out: LexFlags = {};
  if (bits & 1) out.ngsl = true;
  if (bits & 2) out.bsl = true;
  if (lexiconIds[i]!.includes(" ")) out.mwe = true;
  if (bits & 4) out.watch = true;
  if (bits & 8) out.stop = true;
  if (bits & 16) out.phrasal = true;
  if (bits & 32) out.grad = true;
  return out;
}

export function getLexEntry(id: string): LexEntry | undefined {
  const i = index.get(id);
  if (i === undefined) return undefined;
  const ospm = Number(ospmList[i] || 0);
  return { id: lexiconIds[i]!, level: LEVEL_ORDER[Number(LEVELS[i]) - 1]!, rank: i + 1, ospm: ospm > 0 ? ospm : null, pos: [], flags: flagsOf(i), domains: [] };
}
export function isLexId(id: string): boolean { return index.has(id); }
export function isStopId(id: string): boolean { const i = index.get(id); return i !== undefined && (bitsOf(i) & 8) !== 0; }
export const watchlistIds: readonly string[] = lexiconIds.filter((_, i) => (bitsOf(i) & 4) !== 0);
export const mweIds: ReadonlySet<string> = new Set(lexiconIds.filter((id) => id.includes(" ")));
export const phrasalIds: ReadonlySet<string> = new Set(lexiconIds.filter((_, i) => (bitsOf(i) & 16) !== 0));
export const gradableIds: ReadonlySet<string> = new Set(lexiconIds.filter((_, i) => (bitsOf(i) & 32) !== 0));
